import {INCIDENT_TYPES,SEVERITIES,OB_TYPES,validateIncident,validateOccurrence,createRecord,simulateSync,acknowledge,closeIncident,deliveryLabel} from './logic.mjs';

const KEY='smartops-ux-demo-v2';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v)=>v?new Date(v).toLocaleString('en-ZW',{dateStyle:'medium',timeStyle:'short'}):'—';
const now=()=>new Date().toISOString();
const newId=()=> (globalThis.crypto?.randomUUID?.() || `demo-${Date.now()}-${Math.floor(Math.random()*1e8)}`);
function fresh(){return {role:null,route:'login',selected:null,online:false,nextNumber:42,toast:'',records:[{
  id:'example-server-41',type:'incident',siteId:'demo-site-a',site:'Demonstration Site A',createdBy:'Demo Guard',createdAt:'2026-10-18T09:12:00+02:00',eventTime:'2026-10-18T09:05:00+02:00',delivery:'received',serverRef:'DEMO-INC-2026-0041',receivedAt:'2026-10-18T09:15:00+02:00',acknowledgedAt:null,closedAt:null,typeName:'Property Damage',severity:'Medium',description:'Damaged external gate latch noticed during routine inspection. No immediate danger observed.',actions:'Reported to shift supervisor by telephone.',updates:[]
 }],errors:{}};}
let model;
try{model={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'null')}; if(!Array.isArray(model.records))model=fresh();}catch{model=fresh();}
const save=()=>localStorage.setItem(KEY,JSON.stringify({...model,toast:''}));
const set=(change)=>{Object.assign(model,change);save();render();};
const go=(route,selected=null)=>set({route,selected,errors:{},toast:''});
function notify(msg){model.toast=msg;save();render();}
const btn=(name,action,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${name}</button>`;
const chip=(state)=>`<span class="tag ${escape(state)}">${escape(deliveryLabel(state))}</span>`;
function page(title,subtitle=''){return `<div class="pagehead"><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>`;}
function alertBox(type,title,body){return `<div class="alert ${type}"><strong>${title}</strong>${body}</div>`;}
function header(){return `<header class="top"><div class="brandrow"><div class="identity"><div class="shield" aria-hidden="true">⬡</div><div><div class="brand">Baseguard SmartOps</div><div class="subbrand">${model.role==='supervisor'?'Supervisor Console':'Security Operations • Demonstration Site A'}</div></div></div><span class="demo">UX DEMO</span></div><div class="statusline"><button class="net ${model.online?'on':''}" data-action="toggle-online" aria-label="Toggle simulated connectivity"><span class="dot"></span>${model.online?'Simulated Online':'Simulated Offline'} ↔</button><button class="account" data-action="logout">Switch role ↗</button></div>${model.role==='supervisor'?`<div class="desktopnav">${[['dashboard','Overview'],['inbox','Incident Inbox'],['supervisor-ob','Occurrence Book']].map(([r,l])=>`<button class="${model.route===r?'active':''}" data-route="${r}">${l}</button>`).join('')}</div>`:''}</header>`;}
function nav(){const tabs=[['today','⌂','Today'],['ob','▤','OB'],['incidents','⚠','Incidents'],['handover','⇄','Handover']];return `<nav class="bottom" aria-label="Guard navigation">${tabs.map(([route,i,label])=>`<button data-route="${route}" class="${model.route===route?'active':''}"><span class="symbol" aria-hidden="true">${i}</span>${label}</button>`).join('')}</nav>`;}
function login(){return `<section class="signin"><div class="logo">⬡</div><h1>SmartOps</h1><p class="muted">Baseguard security reporting prototype</p><div class="alert">This is an interactive <strong>fictional demonstration</strong>. No live staff authentication, incident delivery or Baseguard integration.</div><div class="card"><h2>Choose a demonstration role</h2>${btn('Continue as Guard','login-guard')}${btn('Continue as Supervisor','login-supervisor','secondary')}<p class="notes">Prototype sign-in only. The production apps use authenticated accounts and site authorization.</p></div></section>`;}
function today(){const pending=model.records.filter(r=>['queued','failed'].includes(r.delivery)).length; const incidents=model.records.filter(r=>r.type==='incident');return `${page("Today's Duty",'Demo Officer · Demonstration Site A')}<div class="card"><div class="row"><div><span class="listTitle">Assigned duty</span><h2 style="margin:5px 0">Demonstration Site A</h2><div class="muted">Training shift • Prototype</div></div><span class="tag received">On duty (demo)</span></div></div>${pending?alertBox('','Reports awaiting sync',`${pending} locally saved report(s). These have <strong>not</strong> reached the supervisor.`):alertBox('green','Queue clear','No locally pending reports in this demonstration.')}<div class="section-title">Quick actions</div><div class="quick"><button data-route="incident-form" class="action"><span class="emoji">⚠</span><strong>Report Incident</strong><span>Record a security incident</span></button><button data-route="ob-form" class="action"><span class="emoji">▤</span><strong>New OB Entry</strong><span>Log routine activities</span></button><button data-route="incidents" class="action"><span class="emoji">▥</span><strong>My Incidents</strong><span>Review existing reports</span></button><button data-route="sync" class="action"><span class="emoji">⇅</span><strong>Sync Queue</strong><span>Pending and failed records</span></button></div><div class="section-title">Recent activity</div>${model.records.length?model.records.slice(0,3).map(recordCard).join(''):`<div class="card empty">No activity yet.</div>`}<div class="aside">Urgent situations still require the approved telephone or radio escalation process. This app alone does not dispatch help.</div>`;}
function incidentForm(){const errors=model.errors||{};const val=old=>escape(old||'');return `${page('Report Incident','Enter factual details about what happened at your assigned site.')} ${alertBox('urgent','Emergency procedure','For immediate danger, use your approved telephone or radio procedure. Saving an incident here does not alert emergency responders.')}<form id="incident-form"><div class="card"><label class="field">Incident type *<select name="type"><option value="">Select incident type</option>${INCIDENT_TYPES.map(c=>`<option ${model.draft?.type===c?'selected':''}>${escape(c)}</option>`).join('')}</select>${errors.type?`<span class="error">${errors.type}</span>`:''}</label><label class="field">Severity *<select name="severity"><option value="">Choose severity</option>${SEVERITIES.map(c=>`<option ${model.draft?.severity===c?'selected':''}>${c}</option>`).join('')}</select>${errors.severity?`<span class="error">${errors.severity}</span>`:''}</label><label class="field">Time of incident *<input type="datetime-local" name="eventTime" value="${escape(model.draft?.eventTime||new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16))}"/>${errors.eventTime?`<span class="error">${errors.eventTime}</span>`:''}</label><label class="field">What happened? * <small>(20+ characters)</small><textarea name="description" placeholder="Describe what you observed, without speculation.">${val(model.draft?.description)}</textarea>${errors.description?`<span class="error">${errors.description}</span>`:''}</label><label class="field">Actions taken <small>(optional)</small><textarea name="actions" style="min-height:82px" placeholder="E.g. supervisor informed by phone.">${escape(model.draft?.actions||'')}</textarea></label></div><div class="actionbar"><button type="submit" class="btn">Save incident to local demo queue</button>${btn('Cancel','cancel-form','ghost')}</div></form><p class="notes">In the prototype, reports are stored in this browser only. No Baseguard data is transmitted.</p>`;}
function obForm(){const e=model.errors||{};return `${page('New OB Entry','Record a routine occurrence at your assigned site.')}<form id="ob-form"><div class="card"><label class="field">Category *<select name="category"><option value="">Select category</option>${OB_TYPES.map(x=>`<option>${escape(x)}</option>`).join('')}</select>${e.category?`<span class="error">${e.category}</span>`:''}</label><label class="field">Occurrence details *<textarea name="description" placeholder="What happened?"></textarea>${e.description?`<span class="error">${e.description}</span>`:''}</label></div><button type="submit" class="btn">Save occurrence locally</button>${btn('Cancel','cancel-form','ghost')}</form>`;}
function submission(){const r=findSelected();if(!r)return notFound();return `${page('Submission Status',r.type==='incident'?'Incident report':'Occurrence-book entry')}${alertBox(r.delivery==='received'?'green':'',r.delivery==='received'?'Simulated server receipt':'Saved in this browser',r.delivery==='received'?'This demonstration record was marked received using the simulated sync control.':'Pending Sync. This record is NOT delivered to Baseguard or any supervisor.') }<div class="card"><div class="row"><div><span class="listTitle">Local reference</span><h2 style="margin:5px 0">${escape(r.id.slice(0,13))}</h2></div>${chip(r.delivery)}</div><div class="divider"></div><div class="muted">${escape(r.description.slice(0,150))}</div><div class="notes" style="margin-top:12px">Created: ${fmt(r.createdAt)}${r.serverRef?`<br>Demo server ref: ${escape(r.serverRef)}`:''}</div></div>${btn('View Sync Queue','to-sync')}${btn('Open Record Details','to-details','secondary')}${btn('Back to Today','to-today','ghost')}`;}
function recordCard(r){return `<button class="incident" data-record="${escape(r.id)}"><div class="row"><span class="metadata">${escape(r.serverRef||r.id.slice(0,15))}</span>${chip(r.delivery)}</div><strong>${escape(r.type==='incident'?(r.typeName||'Incident'):(r.category||'Occurrence'))}</strong><div class="summary">${escape((r.description||'').slice(0,135))}</div><div class="metadata" style="margin-top:8px">${fmt(r.eventTime)} · ${escape(r.site)}</div></button>`;}
function incidents(){return `${page('My Incidents','Track both locally saved and server-received demonstration records.')}${btn('+ Report Incident','to-incident-form')}<div class="section-title">Incident reports</div>${model.records.filter(r=>r.type==='incident').map(recordCard).join('')||`<div class="card empty">No incident reports.</div>`}${btn('View Sync Queue','to-sync','secondary')}`;}
function obs(){return `${page('Occurrence Book','Chronological security-post records')}${btn('+ New OB Entry','to-ob-form')}${model.records.filter(r=>r.type==='occurrence').map(recordCard).join('')||`<div class="card empty">No occurrence records yet.</div>`}`;}
function details(){const r=findSelected();if(!r)return notFound();return `${page(r.type==='incident'?'Incident Details':'Occurrence Details',escape(r.serverRef||r.id.slice(0,17)))}<div class="card"><div class="row">${chip(r.delivery)}${r.severity?`<span class="tag ${r.severity.toLowerCase()}">${escape(r.severity)} severity</span>`:''}</div><h2 style="margin-top:16px">${escape(r.type==='incident'?r.typeName:r.category)}</h2><p>${escape(r.description)}</p>${r.actions?`<div class="aside"><strong>Actions taken</strong><br>${escape(r.actions)}</div>`:''}<div class="divider"></div><div class="notes">Site: ${escape(r.site)}<br>Event: ${fmt(r.eventTime)}<br>Saved locally: ${fmt(r.createdAt)}<br>Server received (demo): ${fmt(r.receivedAt)}<br>Supervisor acknowledged (demo): ${fmt(r.acknowledgedAt)}</div></div>${r.delivery==='queued'?alertBox('','Not yet delivered','This record exists only in the local browser demo.'):''}${r.type==='incident'?`<div class="card"><h2>Follow-up timeline</h2>${r.updates.length?r.updates.map(u=>`<div class="step"><strong>${escape(u.action)} · ${fmt(u.at)}</strong>${escape(u.note||'By '+u.by)}</div>`).join(''):'<p class="notes">No supervisor actions yet.</p>'}</div>`:''}${btn('Back to History','back-history','secondary')}`;}
function sync(){const queued=model.records.filter(r=>['queued','failed'].includes(r.delivery));return `${page('Offline Sync Queue','Review locally saved records and simulate delivery.')}${alertBox(model.online?'green':'','Connectivity simulator',model.online?'Simulated connection is ON. Press the delivery button to simulate successful server receipt.':'Simulated connection is OFF. Records remain on this browser; there is no automatic delivery.') }<div class="grid3"><div class="stat"><strong>${queued.length}</strong><span>Pending</span></div><div class="stat"><strong>${model.records.filter(x=>x.delivery==='received').length}</strong><span>Received</span></div><div class="stat"><strong>${model.records.filter(x=>x.delivery==='acknowledged').length}</strong><span>Acknowledged</span></div></div><div class="section-title">Queue</div>${queued.map(recordCard).join('')||`<div class="card empty">No locally pending records.</div>`}${btn('Simulate server receipt','simulate-sync','',!model.online||queued.length===0?'disabled':'')}${btn('Simulate delivery failure','simulate-failure','secondary',!queued.length?'disabled':'')}<p class="notes">Simulation only: no network request or remote database call is made. Actual SQLite/secure synchronization is part of the native app starter and must be independently tested.</p>`;}
function handover(){return `${page('Shift Handover','Design milestone — implementation follows the incident workflow.')}<div class="card"><h2>Upcoming workflow</h2><div class="steps"><div class="step"><strong>1 · Outgoing guard</strong>Prepare notes and outstanding issues.</div><div class="step"><strong>2 · Submit</strong>Wait for confirmed server receipt.</div><div class="step"><strong>3 · Incoming guard</strong>Read, acknowledge or flag a discrepancy.</div></div></div>${alertBox('','Not yet interactive','The Sprint 1 prototype intentionally does not simulate successful handover transmission. Continue using existing official procedures.')}`;}
function dashboard(){const received=model.records.filter(r=>r.type==='incident'&&!['queued','failed'].includes(r.delivery));return `${page('Operations Overview','Authorized site: Demonstration Site A · Fictional records only')}<div class="grid3"><div class="stat"><strong>${received.length}</strong><span>Received incidents</span></div><div class="stat"><strong>${received.filter(r=>r.delivery==='received').length}</strong><span>To acknowledge</span></div><div class="stat"><strong>${received.filter(r=>r.delivery==='closed').length}</strong><span>Closed</span></div></div><div class="section-title">Incident inbox</div>${received.map(recordCard).join('')||`<div class="card empty">No received incidents in this demo.</div>`}<div class="aside">Supervisors cannot see records in a guard's offline queue until those records have been synchronized to the server.</div>`;}
function inbox(){const received=model.records.filter(r=>r.type==='incident'&&!['queued','failed'].includes(r.delivery));return `${page('Incident Inbox','Review, acknowledge and close received demonstration incidents.')}${received.map(recordCard).join('')||`<div class="card empty">No received incidents yet.</div>`}`;}
function supervisorOb(){const o=model.records.filter(r=>r.type==='occurrence'&&!['queued','failed'].includes(r.delivery));return `${page('Occurrence Book Explorer','Received occurrence entries for Demonstration Site A')}${o.map(recordCard).join('')||`<div class="card empty">No received occurrence entries.</div>`}`;}
function review(){const r=findSelected();if(!r||['queued','failed'].includes(r.delivery))return notFound();return `${page('Incident Review',escape(r.serverRef||''))}<div class="card"><div class="row">${chip(r.delivery)}<span class="tag ${String(r.severity||'low').toLowerCase()}">${escape(r.severity)} severity</span></div><h2 style="margin-top:15px">${escape(r.typeName)}</h2><p>${escape(r.description)}</p><div class="notes">Event time: ${fmt(r.eventTime)}<br>Received: ${fmt(r.receivedAt)}</div>${r.actions?`<div class="aside" style="margin-top:12px"><strong>Guard actions</strong><br>${escape(r.actions)}</div>`:''}</div>${r.delivery==='received'?btn('Acknowledge Incident','acknowledge'):''}${r.delivery==='acknowledged'?`<form id="close-form"><div class="card"><label class="field">Resolution note *<textarea name="note" placeholder="Explain what was done to resolve this incident."></textarea></label><button type="submit" class="btn">Close Incident (demo)</button></div></form>`:''}${r.delivery==='closed'?alertBox('green','Incident closed',`Resolved on ${fmt(r.closedAt)}`):''}<div class="card"><h2>Follow-up history</h2>${r.updates.map(u=>`<div class="step"><strong>${escape(u.action)} · ${fmt(u.at)}</strong>${escape(u.note||u.by)}</div>`).join('')||`<div class="muted">No updates yet.</div>`}</div>${btn('Back to Inbox','to-inbox','secondary')}`;}
function findSelected(){return model.records.find(r=>r.id===model.selected);}
function notFound(){return `${page('Record unavailable','This record may have been removed from the prototype.')}${btn('Go to Today','to-today')}`;}
function render(){const app=document.getElementById('app');const supervisor=model.role==='supervisor';const views={login,today,'incident-form':incidentForm,'ob-form':obForm,submission,incidents,ob:obs,details,sync,handover,dashboard,inbox,review,'supervisor-ob':supervisorOb};if(!model.role&&model.route!=='login')model.route='login';const content=(views[model.route]||login)();app.innerHTML=`<div class="shell ${supervisor?'wide':''}">${model.role?header():''}<main class="content">${model.toast?`<div role="status" class="toast">${escape(model.toast)}</div>`:''}${content}</main>${model.role==='guard'?nav():''}</div>`;document.title='SmartOps · '+model.route;}
function dispatch(action){switch(action){case 'login-guard':set({role:'guard',route:'today'});break;case 'login-supervisor':set({role:'supervisor',route:'dashboard'});break;case 'logout':set({role:null,route:'login',selected:null});break;case 'toggle-online':set({online:!model.online,toast:'Connectivity simulator changed. No real network traffic.'});break;case 'to-incident-form':go('incident-form');break;case 'to-ob-form':go('ob-form');break;case 'cancel-form':set({route:'today',errors:{},draft:null});break;case 'to-sync':go('sync');break;case 'to-details':go('details',model.selected);break;case 'to-today':go('today');break;case 'to-inbox':go('inbox');break;case 'back-history':go(model.role==='supervisor'?'inbox':(findSelected()?.type==='incident'?'incidents':'ob'));break;case 'simulate-failure':set({records:model.records.map(r=>r.delivery==='queued'?{...r,delivery:'failed'}:r),toast:'Simulated submission failure. Report remains in local queue.'});break;case 'simulate-sync':{if(!model.online){notify('Turn on simulated connectivity first.');break;}const {records,nextNumber}=simulateSync(model.records,now(),model.nextNumber);set({records,nextNumber,toast:'Demo receipt recorded. No real data was sent.'});break;}case 'acknowledge':{const r=findSelected();try{set({records:model.records.map(x=>x.id===r?.id?acknowledge(x,now()):x),toast:'Demo supervisor acknowledgment recorded.'});}catch(e){notify(e.message);}break;}default:break;}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-route],[data-record]');if(!target)return;if(target.dataset.route){go(target.dataset.route);return;}if(target.dataset.record){go(model.role==='supervisor'?'review':'details',target.dataset.record);return;}dispatch(target.dataset.action);});
document.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(e.target.id==='incident-form'){const input={type:data.type,severity:data.severity,eventTime:data.eventTime,description:String(data.description||'').trim()};const errors=validateIncident(input);if(Object.keys(errors).length){set({errors,draft:{...input,actions:String(data.actions||'')}});return;}const record=createRecord('incident',{typeName:input.type,severity:input.severity,description:input.description,eventTime:new Date(input.eventTime).toISOString(),actions:String(data.actions||'').trim()},newId(),now());set({records:[record,...model.records],route:'submission',selected:record.id,errors:{},draft:null,toast:'Saved locally in demo browser storage. Not delivered.'});}
 if(e.target.id==='ob-form'){const input={category:data.category,description:String(data.description||'').trim()};const errors=validateOccurrence(input);if(Object.keys(errors).length){set({errors});return;}const record=createRecord('occurrence',input,newId(),now());set({records:[record,...model.records],route:'submission',selected:record.id,errors:{},toast:'Saved locally in demo browser storage. Not delivered.'});}
 if(e.target.id==='close-form'){const r=findSelected();try{set({records:model.records.map(x=>x.id===r?.id?closeIncident(x,now(),data.note):x),toast:'Incident closed in the demo only.'});}catch(e){notify(e.message);}}
});
render();
